CREATE TYPE split_mode AS ENUM ('equal','percentage'); CREATE TYPE tab_status AS ENUM ('active','closing','locked','settling','settled'); CREATE TYPE member_status AS ENUM ('pending','active','inactive','removed'); CREATE TYPE expense_status AS ENUM ('active','disputed','void'); CREATE TYPE approval_kind AS ENUM ('join','inactive','remove','close');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),privy_id text UNIQUE,name text NOT NULL,email text,preferred_currency text NOT NULL DEFAULT 'NGN',wallet_address text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tabs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,emoji text,creator_id uuid NOT NULL REFERENCES users(id),split_mode split_mode NOT NULL,status tab_status NOT NULL DEFAULT 'active',ledger_version int NOT NULL DEFAULT 1,invite_code text UNIQUE NOT NULL,invite_generation int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz);
CREATE TABLE tab_members(tab_id uuid REFERENCES tabs(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id),status member_status NOT NULL DEFAULT 'pending',percentage numeric(6,3),joined_at timestamptz,inactive_at timestamptz,PRIMARY KEY(tab_id,user_id));
CREATE TABLE expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tab_id uuid NOT NULL REFERENCES tabs(id) ON DELETE CASCADE,payer_id uuid NOT NULL REFERENCES users(id),description text NOT NULL,category text,original_amount numeric(18,2) NOT NULL,original_currency text NOT NULL,fx_rate_to_usd numeric(24,10) NOT NULL,locked_usd_value numeric(18,6) NOT NULL,paid_at timestamptz NOT NULL,fx_timestamp timestamptz NOT NULL,proof_url text,status expense_status NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expense_beneficiaries(expense_id uuid REFERENCES expenses(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id),PRIMARY KEY(expense_id,user_id));
CREATE TABLE disputes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),expense_id uuid NOT NULL REFERENCES expenses(id) ON DELETE CASCADE,raised_by uuid NOT NULL REFERENCES users(id),reason text NOT NULL,note text,resolved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tab_id uuid NOT NULL REFERENCES tabs(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id),kind approval_kind NOT NULL,subject_user_id uuid REFERENCES users(id),ledger_version int NOT NULL,approved_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tab_id uuid NOT NULL REFERENCES tabs(id),from_user_id uuid NOT NULL REFERENCES users(id),to_user_id uuid NOT NULL REFERENCES users(id),amount_usd numeric(18,6) NOT NULL,amount_usdc numeric(18,6) NOT NULL,arc_tx_hash text,settled_at timestamptz);
CREATE INDEX expenses_tab_idx ON expenses(tab_id); CREATE INDEX approvals_tab_version_idx ON approvals(tab_id,ledger_version);